def three_point(a, m, b):
    e = (a + 4 * m + b) / 6
    sd = (b - a) / 6
    return (round(e, 2), round(sd, 2))

import math

def estimate_range(tasks):
    total_e = sum((a + 4 * m + b) / 6 for a, m, b in tasks)
    sd = math.sqrt(sum(((b - a) / 6) ** 2 for a, m, b in tasks))
    return (round(total_e, 1), round(total_e - 2 * sd, 1), round(total_e + 2 * sd, 1))
